import {ReportQueueView} from '../../src/features/report-queue.ts';import type {Experiment} from '../../src/domain/types.ts';
export function createQueueFixture(){let confirmation=true,fail='b',pending=false,saving=false,release:(()=>void)|undefined,calls:string[]=[],progress:((s:string)=>void)|undefined;const exps=[{id:'a',name:'测试力学实验'},{id:'b',name:'测试光学实验'},{id:'c',name:'测试电学实验'}] as Experiment[];const view=new ReportQueueView(exps,async(id,signal,p,phase)=>{calls.push(id);progress=p;if(pending){phase(saving?'saving':'computing');await new Promise<void>(r=>release=r);}if(id===fail)throw Error('模拟错误 <img src=x> '+ '长错误说明'.repeat(90));},async()=>confirmation);view.mount(document.querySelector<HTMLElement>('#queue-host')!);return {state:()=>({items:view.queue.items,running:view.queue.running,paused:view.queue.paused,calls,saving:view.isSaving}),confirm:(v:boolean)=>confirmation=v,fail:(v:string)=>fail=v,pending:(v:boolean,save=false)=>{pending=v;saving=save;},release:()=>release?.(),late:()=>progress?.('旧进度'),leave:()=>view.leave()};}
